}

object ArchiveRightsPolicy {
    fun isOpen(rights: String?, licenseUrl: String?): Boolean {
        val text = (rights.orEmpty() + " " + licenseUrl.orEmpty()).lowercase()
        return OPEN_MARKERS.any(text::contains)
    }

    private val OPEN_MARKERS = listOf(
        "public domain",
        "publicdomain",
        "creativecommons.org",
        "creative commons",
        "cc0",
        "cc-by",
        "cc by",
        "cc-by-sa",
        "cc by-sa"
    )
}

object WikimediaSubtitleSupport {
    fun timedTextUrl(fileTitle: String, language: String): String =
        "https://commons.wikimedia.org/w/api.php" +
            "?action=timedtext" +
            "&title=" + encode(fileTitle) +
            "&lang=" + encode(language) +
            "&trackformat=vtt"

    fun looksLikeSubtitle(body: String): Boolean {
        val value = body.trimStart()
        return value.startsWith("WEBVTT", ignoreCase = true) ||
            Regex("""\d{1,2}:\d{2}[:.]\d{2}.*-->""").containsMatchIn(value)
    }

    private fun encode(value: String): String =
        URLEncoder.encode(value, "UTF-8").replace("+", "%20")
}

object MovieCatalogDeduplicator {
    fun deduplicate(items: List<VodItem>): List<VodItem> =
        items.distinctBy { item ->
            normalize(item.title) + "|" + item.year.orEmpty()
        }

    internal fun normalize(value: String): String =
        value.uppercase()
            .replace(Regex("[^A-Z0-9]+"), " ")
            .trim()
}

object VodSubtitleSupport {
    fun isSupportedFile(name: String): Boolean {
        val clean = name.substringBefore('?').lowercase()
        return clean.endsWith(".srt") ||
            clean.endsWith(".vtt") ||
            clean.endsWith(".ttml") ||
            clean.endsWith(".xml")
    }

    fun fromUrl(url: String): VodSubtitle? {
        val clean = url.substringBefore('?').lowercase()
        val mime = when {
            clean.endsWith(".srt") -> "application/x-subrip"
            clean.endsWith(".vtt") -> "text/vtt"
            clean.endsWith(".ttml") || clean.endsWith(".xml") -> "application/ttml+xml"
            else -> return null
        }
        val language = languageFromName(clean)
        return VodSubtitle(
            uri = url,
            language = language,
            label = when (language) {
                "pt-BR" -> "Português (Brasil)"
                "pt" -> "Português"
                "en" -> "English"
                "es" -> "Español"
                else -> "Legenda"
            },
            mimeType = mime,
            isDefault = language == "pt-BR" || language == "pt"
        )
    }

    fun preferPortuguese(subtitles: List<VodSubtitle>): List<VodSubtitle> =
        subtitles.distinctBy(VodSubtitle::uri)
            .sortedWith(
                compareBy<VodSubtitle> {
                    when (it.language) {
                        "pt-BR" -> 0
                        "pt" -> 1
                        "en" -> 2
                        "es" -> 3
                        else -> 4
                    }
                }.thenBy(VodSubtitle::label)
            )

    internal fun languageFromName(value: String): String {
        val lower = value.lowercase()
        return when {
            "pt-br" in lower || "pt_br" in lower || "brazil" in lower ||
                "portuguese-brazil" in lower -> "pt-BR"
            Regex("(^|[._-])pt([._-]|$)").containsMatchIn(lower) ||
                "portuguese" in lower -> "pt"
            Regex("(^|[._-])en([._-]|$)").containsMatchIn(lower) ||
                "english" in lower -> "en"
            Regex("(^|[._-])es([._-]|$)").containsMatchIn(lower) ||
                "spanish" in lower -> "es"
            else -> "und"
        }
    }
}

